// are the agent's own bookkeeping and are deliberately hidden
// from the public Control Plane API.
type VMRuntime struct {
	CPUUsagePercent  *float32  `json:"cpu_usage_percent,omitempty"`
	GuestHostname    *string   `json:"guest_hostname,omitempty"`
	GuestIPAddresses *[]string `json:"guest_ip_addresses,omitempty"`
	GuestOs          *string   `json:"guest_os,omitempty"`
	MemoryUsedMib    *int64    `json:"memory_used_mib,omitempty"`

	// QEMUPid PID of the QEMU process, when running.
	QEMUPid *int `json:"qemu_pid,omitempty"`

	// QMPSocketPath Path to the QMP control socket.
	QMPSocketPath     *string `json:"qmp_socket_path,omitempty"`
	SerialConsolePath *string `json:"serial_console_path,omitempty"`

	// VNCEndpoint `host:port` of the QEMU VNC listener, when one is
	// configured. The console-token / console-stream
	// endpoints terminate in front of this — clients never
	// see this address directly.
	VNCEndpoint *string `json:"vnc_endpoint,omitempty"`
}

// VMSpec Full VM specification handed to the agent at create time. The
// Control Plane has already resolved every CP-only key
// (image source, firmware, storage pool, network) into
// agent-consumable values; the agent treats this as the
// complete description of what to bring up.
type VMSpec struct {
	Architecture VMSpecArchitecture `json:"architecture"`

	// CloudInit Cloud-init payload. The agent renders this into a
	// NoCloud datasource ISO and presents it as an extra
	// disk; the rendering happens at create time.
	CloudInit *struct {
		MetaData      *string `json:"meta_data,omitempty"`
		NetworkConfig *string `json:"network_config,omitempty"`
		UserData      *string `json:"user_data,omitempty"`
	} `json:"cloud_init,omitempty"`
	CPUCores int `json:"cpu_cores"`

	// CPUModel QEMU `-cpu` model. Defaults to `host` when not specified by the CP.
	CPUModel string `json:"cpu_model"`

	// Disks Position 0 is the boot disk by convention.
	Disks []VMSpecDisk `json:"disks"`

	// ExtraArgs Additional QEMU command-line arguments. Escape hatch for
	// features the contract does not yet model directly.
	// Operators must understand the implications — there is
	// no validation beyond non-empty strings.
	ExtraArgs *[]string `json:"extra_args,omitempty"`

	// Firmware Firmware to boot with. Resolved by the CP from
	// `(architecture, firmware_type)` or from a pinned
	// `firmware_id`.
	Firmware struct {
		// CodePath Absolute path to the firmware code blob on this node.
		CodePath   string             `json:"code_path"`
		SecureBoot *bool              `json:"secure_boot,omitempty"`
		Type       VMSpecFirmwareType `json:"type"`

		// VarsTemplatePath Absolute path to the firmware NVRAM template; the
		// agent copies it per VM and persists the result.
		VarsTemplatePath *string `json:"vars_template_path,omitempty"`
	} `json:"firmware"`

	// Generation Mirrors `vms.generation` on the CP side. Carried so the
	// agent can include it in `VMDetail.observed_generation`
	// once converged, letting the CP tell whether the runtime
	// has caught up to the latest spec.
	Generation int64 `json:"generation"`

	// Labels Forwarded from the CP for log / metric tagging.
	Labels *map[string]string `json:"labels,omitempty"`

	// MachineType QEMU `-machine` type, e.g. `q35`, `pc-q35-8.2`, `virt`.
	MachineType string `json:"machine_type"`

	// MaxCPUCores Upper bound for CPU hotplug. When omitted, CPU hotplug is
	// disabled and `vms.resize` will return
	// `hot_resize_not_supported` for CPU changes.
	MaxCPUCores *int `json:"max_cpu_cores,omitempty"`

	// MaxMemoryMib Upper bound for memory hotplug. Same semantics as `max_cpu_cores`.
	MaxMemoryMib *int64      `json:"max_memory_mib,omitempty"`
	MemoryMib    int64       `json:"memory_mib"`
	Name         string      `json:"name"`
	Nics         []VMSpecNic `json:"nics"`

	// SerialConsole Serial console device exposed to the guest. The CP picks
	// `ttyS0` for amd64 and `ttyAMA0` for arm64 by default.
	SerialConsole *VMSpecSerialConsole `json:"serial_console,omitempty"`

	// VMUUID Same UUID as the Control Plane's `vms.id`.
	VMUUID openapi_types.UUID `json:"vm_uuid"`
}

// VMSpecArchitecture defines model for VMSpec.Architecture.
type VMSpecArchitecture string

// VMSpecFirmwareType defines model for VMSpec.Firmware.Type.
type VMSpecFirmwareType string

// VMSpecSerialConsole Serial console device exposed to the guest. The CP picks
// `ttyS0` for amd64 and `ttyAMA0` for arm64 by default.
type VMSpecSerialConsole string

// VMSpecDisk Disk attached to a VM. Field semantics match the Control
// Plane's `VmDisk` / `VMCreateDiskSpec` exactly so a disk row
// round-trips through the contract without translation. The
// agent never sees the CP-side `storage_pool_id` UUID — the CP
// resolves it to `storage_pool_path` (an absolute filesystem
// path on this node) before sending the spec.
type VMSpecDisk struct {
	BootOrder *int                 `json:"boot_order,omitempty"`
	Bus       VMSpecDiskBus        `json:"bus"`
	CacheMode *VMSpecDiskCacheMode `json:"cache_mode,omitempty"`

	// DeviceOrder Position on the VM's disk bus; also boot-order tie-breaker.
	DeviceOrder int                `json:"device_order"`
	Discard     *VMSpecDiskDiscard `json:"discard,omitempty"`
	Format      VMSpecDiskFormat   `json:"format"`
	ReadOnly    *bool              `json:"read_only,omitempty"`
	SizeGib     int                `json:"size_gib"`

	// Source Disk image origin. The `kind` discriminates: when `image`,
	// `image_url`, `checksum_sha256` and `image_format` are
	// required (the VM is self-describing; the agent materializes the
	// image into the destination pool's cache on first use). When
	// `blank`, all three must be absent - the agent allocates an
	// empty image of `size_gib` instead.
	Source VMSpecDiskSource `json:"source"`

	// StoragePoolID CP-side pool id, included as a label so the agent can
	// tag logs / metrics. Not used for any path lookup.
	StoragePoolID *openapi_types.UUID `json:"storage_pool_id,omitempty"`

	// StoragePoolPath Absolute filesystem path of the storage pool that backs
	// this disk on this node. The CP picks the pool (or
	// honours the user's pin) and resolves it before send.
	StoragePoolPath string `json:"storage_pool_path"`
}

